WITH valid AS (SELECT *, CASE WHEN dept_name = 'Legal' THEN 1 ELSE 0 END AS is_legal, INITCAP(TRIM(dept_name)) AS dept_name_title FROM departments WHERE dept_name IS NOT NULL) SELECT *, LEAD(is_legal) OVER w_grp AS next_is_legal, LEAD(budget) OVER w_grp AS next_budget, LAG(budget) OVER w_grp AS prev_budget, ROW_NUMBER() OVER w_grp AS event_seq, LAST_VALUE(dept_name, TRUE) OVER (PARTITION BY location ORDER BY is_legal, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_dept_name FROM valid WINDOW w_grp AS (PARTITION BY dept_name ORDER BY is_legal, id)
